<?php
namespace App\Http\Requests\Tenant\Task; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class TaskRequest extends FormRequest { public function authorize():bool{return (bool)$this->user('tenant')?->can($this->isMethod('post')?'tasks.create':'tasks.update');} public function rules():array{return ['title'=>['required','string','max:500'],'description'=>['nullable','string','max:10000'],'status'=>['required',Rule::in(['todo','in_progress','blocked','completed','cancelled'])],'priority'=>['required',Rule::in(['low','normal','high','urgent'])],'assigned_to'=>['nullable','exists:users,id'],'due_at'=>['nullable','date'],'related_type'=>['nullable',Rule::in(['contact','company','ticket','conversation'])],'related_id'=>['nullable','integer'],'parent_task_id'=>['nullable','exists:tasks,id'],'tag_ids'=>['nullable','array'],'tag_ids.*'=>['integer','exists:tags,id']];} }
